def transform(grid):
    out = [row[:] for row in grid]
    r = next(i for i, row in enumerate(grid) if any(v != 0 for v in row))
    for c, color in enumerate(grid[r]):
        if color in (2, 8):
            height = 4 if color == 2 else 3
            height = min(height, r)
            for k in range(1, height + 1):
                out[r - k][c] = color if k == height else 1
    return out
